"use client";

import { Copy, Printer } from "lucide-react";
import { Modal } from "@/components/ui/Modal";
import { Button } from "@/components/ui/Button";

/**
 * "Show QR" — the public connect-card link, large, with a QR image.
 * The QR is generated by a public service (api.qrserver.com); no library
 * is bundled. The printable view hides everything but the code + link.
 */
export function ShareLinkModal({
  open,
  onClose,
  url,
  churchName,
  onCopy,
}: {
  open: boolean;
  onClose: () => void;
  url: string;
  churchName: string;
  onCopy: () => void;
}) {
  const qrSrc = url
    ? `https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=8&data=${encodeURIComponent(url)}`
    : "";

  function print() {
    const w = window.open("", "_blank", "width=600,height=760");
    if (!w) return;
    const safeName = churchName.replace(/[<>&]/g, "");
    const safeUrl = url.replace(/[<>&"]/g, "");
    w.document.write(`<!doctype html><html><head><title>Connect card — ${safeName}</title>
<style>
  body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;padding:48px;text-align:center;color:#0f172a}
  h1{font-size:28px;margin:0 0 4px}
  p{margin:0;color:#475569}
  .big{font-size:22px;font-weight:700;margin-top:24px}
  img{margin-top:32px;width:320px;height:320px}
  .url{margin-top:24px;font-size:16px;word-break:break-all;color:#4f46e5}
</style></head><body>
  <h1>${safeName}</h1>
  <p>We're glad you came!</p>
  <p class="big">Scan to fill in your connect card</p>
  <img src="${qrSrc.replace("240x240", "480x480")}" alt="QR code" />
  <p class="url">${safeUrl}</p>
  <script>window.onload=function(){setTimeout(function(){window.print()},300)}</script>
</body></html>`);
    w.document.close();
  }

  return (
    <Modal
      open={open}
      onClose={onClose}
      title="Connect card QR code"
      subtitle="Put this on the welcome desk, the bulletin or the screen."
    >
      <div className="flex flex-col items-center text-center">
        {qrSrc ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={qrSrc}
            alt="QR code for the connect card link"
            width={240}
            height={240}
            className="rounded-2xl border border-slate-200 bg-white p-2"
          />
        ) : (
          <div className="h-60 w-60 animate-pulse rounded-2xl bg-slate-100" />
        )}
        <p className="mt-5 text-xs font-semibold tracking-widest text-slate-400 uppercase">
          Public link
        </p>
        <p className="mt-1 max-w-full break-all text-lg font-bold text-indigo-600">
          {url || "…"}
        </p>
        <p className="mt-4 max-w-sm text-xs leading-relaxed text-slate-500">
          The QR image is generated by a public service (api.qrserver.com) from
          the link above — the link itself contains no visitor data.
        </p>
        <div className="mt-6 flex flex-wrap justify-center gap-2.5">
          <Button variant="secondary" onClick={onCopy} disabled={!url}>
            <Copy className="h-4 w-4" aria-hidden />
            Copy link
          </Button>
          <Button onClick={print} disabled={!url}>
            <Printer className="h-4 w-4" aria-hidden />
            Print
          </Button>
        </div>
      </div>
    </Modal>
  );
}
